CREATE OR REPLACE FUNCTION "ponder_go_srcsync_18e19517cc8ed3ec"."_ponder_go_guard"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'TRUNCATE is unsupported for onchain tables'; END IF;
